// Byte-array primitives.  A "byte string" is a plain Array of integers 0..255.

/** Concatenate any number of byte arrays into a fresh array. */
export function bconcat(...parts) {
  const out = [];
  for (const p of parts) {
    for (let i = 0; i < p.length; i++) out.push(p[i]);
  }
  return out;
}

/** Structural equality of two byte arrays. */
export function bequal(a, b) {
  if (a.length !== b.length) return false;
  for (let i = 0; i < a.length; i++) if (a[i] !== b[i]) return false;
  return true;
}

/** Python-style slice with possibly negative endpoints (step 1 only). */
export function bslice(a, start, stop) {
  const n = a.length;
  let s = start === undefined ? 0 : start;
  let e = stop === undefined ? n : stop;
  if (s < 0) s += n;
  if (e < 0) e += n;
  if (s < 0) s = 0;
  if (e > n) e = n;
  const out = [];
  for (let i = s; i < e; i++) out.push(a[i]);
  return out;
}

/** bytes.lstrip(single byte value) */
export function blstripByte(a, value) {
  let i = 0;
  while (i < a.length && a[i] === value) i++;
  return bslice(a, i, a.length);
}

// The set of bytes that Python's `bytes.strip()` removes with no argument:
// space, \t, \n, \v, \f, \r
const ASCII_WS = [0x20, 0x09, 0x0a, 0x0b, 0x0c, 0x0d];

/** bytes.rstrip() with no argument. */
export function brstripWs(a) {
  let e = a.length;
  while (e > 0 && ASCII_WS.indexOf(a[e - 1]) !== -1) e--;
  return bslice(a, 0, e);
}

/** int.from_bytes(v, 'big') as a BigInt. */
export function bytesToBigIntBE(a) {
  let acc = 0n;
  for (let i = 0; i < a.length; i++) acc = (acc << 8n) | BigInt(a[i]);
  return acc;
}

/** Repeat a single byte value n times. */
export function brepeat(value, n) {
  const out = [];
  for (let i = 0; i < n; i++) out.push(value);
  return out;
}

/** Reverse a copy of a byte array. */
export function breversed(a) {
  const out = [];
  for (let i = a.length - 1; i >= 0; i--) out.push(a[i]);
  return out;
}

/** Latin-1 string (one code unit per byte) -> byte array. */
export function bytesFromLatin1(s) {
  const out = [];
  for (let i = 0; i < s.length; i++) out.push(s.charCodeAt(i) & 0xff);
  return out;
}

// A Python `str` modelled as an array of code points (so astral characters and
// lone surrogates from surrogateescape both behave exactly like CPython).

export class PyStr {
  constructor(cps) {
    this.cps = cps;
  }
  get length() {
    return this.cps.length;
  }
}

/** Build a PyStr from a JavaScript string (surrogate pairs are combined). */
export function strFromJs(s) {
  const cps = [];
  for (let i = 0; i < s.length; i++) {
    const c = s.charCodeAt(i);
    if (c >= 0xd800 && c <= 0xdbff && i + 1 < s.length) {
      const d = s.charCodeAt(i + 1);
      if (d >= 0xdc00 && d <= 0xdfff) {
        cps.push(0x10000 + ((c - 0xd800) << 10) + (d - 0xdc00));
        i++;
        continue;
      }
    }
    cps.push(c);
  }
  return new PyStr(cps);
}

/** Render a PyStr back to a JavaScript string (lone surrogates preserved). */
export function jsFromStr(v) {
  let out = '';
  for (const cp of v.cps) {
    if (cp > 0xffff) {
      const x = cp - 0x10000;
      out += String.fromCharCode(0xd800 + (x >> 10), 0xdc00 + (x & 0x3ff));
    } else {
      out += String.fromCharCode(cp);
    }
  }
  return out;
}

// Exactly the code points for which CPython's Py_UNICODE_ISSPACE() is true.
// Verified against the reference binary via str.rstrip().
const SPACE_SET = new Set([
  0x0009, 0x000a, 0x000b, 0x000c, 0x000d, 0x001c, 0x001d, 0x001e, 0x001f,
  0x0020, 0x0085, 0x00a0, 0x1680,
  0x2000, 0x2001, 0x2002, 0x2003, 0x2004, 0x2005, 0x2006, 0x2007, 0x2008,
  0x2009, 0x200a,
  0x2028, 0x2029, 0x202f, 0x205f, 0x3000,
]);

export function isPySpace(cp) {
  return SPACE_SET.has(cp);
}

/** str.rstrip() with no argument. */
export function rstripStr(v) {
  const cps = v.cps;
  let e = cps.length;
  while (e > 0 && isPySpace(cps[e - 1])) e--;
  return new PyStr(cps.slice(0, e));
}

// Py_UNICODE_ISPRINTABLE: false for the "Other" (C*) and "Separator" (Z*)
// general categories, except that ASCII space is considered printable.
const NONPRINTABLE_RE = /[\p{Cc}\p{Cf}\p{Cs}\p{Co}\p{Cn}\p{Zl}\p{Zp}\p{Zs}]/u;
const printableCache = new Map();

export function isPrintableCp(cp) {
  if (cp === 0x20) return true;
  if (cp >= 0x21 && cp <= 0x7e) return true;
  if (cp < 0x20 || cp === 0x7f) return false;
  const hit = printableCache.get(cp);
  if (hit !== undefined) return hit;
  let ch;
  if (cp > 0xffff) {
    const x = cp - 0x10000;
    ch = String.fromCharCode(0xd800 + (x >> 10), 0xdc00 + (x & 0x3ff));
  } else {
    ch = String.fromCharCode(cp);
  }
  const res = !NONPRINTABLE_RE.test(ch);
  printableCache.set(cp, res);
  return res;
}

// Python exception analogues plus the traceback rendering used by the frozen
// PyInstaller binary.

export class PyException extends Error {
  constructor(typeName) {
    super(typeName);
    this.pyType = typeName;
    // Frames are stored outermost-first, i.e. the order they are printed.
    this.frames = [];
  }
  pyStr() {
    return '';
  }
}

export class PyValueError extends PyException {
  constructor(msg) {
    super('ValueError');
    this.msg = msg;
  }
  pyStr() {
    return this.msg;
  }
}

function hex(n, width) {
  let s = n.toString(16);
  while (s.length < width) s = '0' + s;
  return s;
}

export class PyUnicodeEncodeError extends PyException {
  /**
   * @param {string} encoding  e.g. 'ascii' or 'utf-8'
   * @param {import('./pystr.mjs').PyStr} obj  the offending string
   * @param {number} start  first bad code point index
   * @param {number} end    one past the last bad code point index
   * @param {string} reason
   */
  constructor(encoding, obj, start, end, reason) {
    super('UnicodeEncodeError');
    this.encoding = encoding;
    this.object = obj;
    this.start = start;
    this.end = end;
    this.reason = reason;
  }
  pyStr() {
    const len = this.object.cps.length;
    if (this.start < len && this.end === this.start + 1) {
      const bad = this.object.cps[this.start];
      let rendered;
      if (bad <= 0xff) rendered = '\\x' + hex(bad, 2);
      else if (bad <= 0xffff) rendered = '\\u' + hex(bad, 4);
      else rendered = '\\U' + hex(bad, 8);
      return (
        "'" + this.encoding + "' codec can't encode character '" + rendered +
        "' in position " + this.start + ': ' + this.reason
      );
    }
    return (
      "'" + this.encoding + "' codec can't encode characters in position " +
      this.start + '-' + (this.end - 1) + ': ' + this.reason
    );
  }
}

/** Push a caller frame onto the front of the traceback. */
export function addFrame(err, file, line, fn) {
  if (err instanceof PyException) err.frames.unshift({ file, line, fn });
  return err;
}

/** Render the exact traceback text CPython would emit (trailing newline). */
export function formatTraceback(err) {
  let out = 'Traceback (most recent call last):\n';
  for (const f of err.frames) {
    out += '  File "' + f.file + '", line ' + f.line + ', in ' + f.fn + '\n';
  }
  const detail = err.pyStr();
  out += err.pyType + (detail === '' ? '' : ': ' + detail) + '\n';
  return out;
}

/** The extra line PyInstaller's bootloader prints for an unhandled exception. */
export function pyinstallerFooter(pid) {
  return (
    '[PYI-' + pid + ":ERROR] Failed to execute script 'test19' due to " +
    'unhandled exception!\n'
  );
}

// UTF-8 / ASCII codecs with CPython's exact error boundaries, plus the
// surrogateescape and "replace" decode handlers.

import { PyStr } from './pystr.mjs';
import { PyUnicodeEncodeError } from './pyerrors.mjs';

const SURROGATES_NOT_ALLOWED = 'surrogates not allowed';
const ASCII_REASON = 'ordinal not in range(128)';

function isSurrogate(cp) {
  return cp >= 0xd800 && cp <= 0xdfff;
}

/**
 * str.encode() — strict UTF-8.  Lone surrogates raise UnicodeEncodeError with
 * consecutive bad code points collapsed into a single range, exactly like
 * CPython's unicode_encode_utf8().
 */
export function encodeUtf8(v) {
  const cps = v.cps;
  const out = [];
  for (let i = 0; i < cps.length; i++) {
    const cp = cps[i];
    if (cp < 0x80) {
      out.push(cp);
    } else if (cp < 0x800) {
      out.push(0xc0 | (cp >> 6), 0x80 | (cp & 0x3f));
    } else if (isSurrogate(cp)) {
      let end = i + 1;
      while (end < cps.length && isSurrogate(cps[end])) end++;
      throw new PyUnicodeEncodeError('utf-8', v, i, end, SURROGATES_NOT_ALLOWED);
    } else if (cp < 0x10000) {
      out.push(0xe0 | (cp >> 12), 0x80 | ((cp >> 6) & 0x3f), 0x80 | (cp & 0x3f));
    } else {
      out.push(
        0xf0 | (cp >> 18),
        0x80 | ((cp >> 12) & 0x3f),
        0x80 | ((cp >> 6) & 0x3f),
        0x80 | (cp & 0x3f)
      );
    }
  }
  return out;
}

/**
 * str.encode('ascii') — strict.  Consecutive unencodable code points collapse
 * into one range (CPython's unicode_encode_ucs1()).
 */
export function encodeAscii(v) {
  const cps = v.cps;
  const out = [];
  for (let i = 0; i < cps.length; i++) {
    const cp = cps[i];
    if (cp < 0x80) {
      out.push(cp);
    } else {
      let end = i + 1;
      while (end < cps.length && cps[end] >= 0x80) end++;
      throw new PyUnicodeEncodeError('ascii', v, i, end, ASCII_REASON);
    }
  }
  return out;
}

function isCont(b) {
  return b >= 0x80 && b <= 0xbf;
}

/**
 * Walk a byte array as UTF-8 and hand every well-formed code point plus every
 * ill-formed byte range to the supplied callbacks.  The range boundaries match
 * CPython's utf8_decode() error codes, which is also what V8 uses to place its
 * U+FFFD replacement characters.
 */
function scanUtf8(data, onChar, onError) {
  const n = data.length;
  let i = 0;
  while (i < n) {
    const b = data[i];
    if (b < 0x80) {
      onChar(b);
      i += 1;
      continue;
    }
    if (b < 0xc2) {
      onError(i, i + 1);
      i += 1;
      continue;
    }
    if (b < 0xe0) {
      if (n - i < 2) {
        onError(i, n);
        i = n;
        continue;
      }
      const b2 = data[i + 1];
      if (!isCont(b2)) {
        onError(i, i + 1);
        i += 1;
        continue;
      }
      onChar(((b & 0x1f) << 6) | (b2 & 0x3f));
      i += 2;
      continue;
    }
    if (b < 0xf0) {
      if (n - i < 3) {
        if (n - i < 2) {
          onError(i, n);
          i = n;
          continue;
        }
        const b2t = data[i + 1];
        const badPrefix =
          !isCont(b2t) ||
          (b2t < 0xa0 ? b === 0xe0 : b === 0xed && b2t >= 0xa0);
        if (badPrefix) {
          onError(i, i + 1);
          i += 1;
        } else {
          onError(i, n);
          i = n;
        }
        continue;
      }
      const b2 = data[i + 1];
      const b3 = data[i + 2];
      if (!isCont(b2) || (b === 0xe0 && b2 < 0xa0) || (b === 0xed && b2 >= 0xa0)) {
        onError(i, i + 1);
        i += 1;
        continue;
      }
      if (!isCont(b3)) {
        onError(i, i + 2);
        i += 2;
        continue;
      }
      onChar(((b & 0x0f) << 12) | ((b2 & 0x3f) << 6) | (b3 & 0x3f));
      i += 3;
      continue;
    }
    if (b < 0xf5) {
      if (n - i < 4) {
        if (n - i < 2) {
          onError(i, n);
          i = n;
          continue;
        }
        const b2t = data[i + 1];
        const badPrefix =
          !isCont(b2t) ||
          (b2t < 0x90 ? b === 0xf0 : b === 0xf4 && b2t >= 0x90);
        if (badPrefix) {
          onError(i, i + 1);
          i += 1;
          continue;
        }
        if (n - i < 3) {
          onError(i, n);
          i = n;
          continue;
        }
        const b3t = data[i + 2];
        if (!isCont(b3t)) {
          onError(i, i + 2);
          i += 2;
          continue;
        }
        onError(i, n);
        i = n;
        continue;
      }
      const b2 = data[i + 1];
      const b3 = data[i + 2];
      const b4 = data[i + 3];
      if (!isCont(b2) || (b === 0xf0 && b2 < 0x90) || (b === 0xf4 && b2 >= 0x90)) {
        onError(i, i + 1);
        i += 1;
        continue;
      }
      if (!isCont(b3)) {
        onError(i, i + 2);
        i += 2;
        continue;
      }
      if (!isCont(b4)) {
        onError(i, i + 3);
        i += 3;
        continue;
      }
      onChar(
        ((b & 0x07) << 18) | ((b2 & 0x3f) << 12) | ((b3 & 0x3f) << 6) | (b4 & 0x3f)
      );
      i += 4;
      continue;
    }
    onError(i, i + 1);
    i += 1;
  }
}

/** bytes.decode('utf-8', 'surrogateescape') -> PyStr */
export function decodeUtf8Surrogateescape(data) {
  const cps = [];
  scanUtf8(
    data,
    (cp) => cps.push(cp),
    (s, e) => {
      for (let k = s; k < e; k++) cps.push(0xdc00 + data[k]);
    }
  );
  return new PyStr(cps);
}

/**
 * The lossy decode that the JS runtime already applied to process.argv: one
 * U+FFFD per maximal ill-formed subpart.  Returns a JavaScript string.
 */
export function decodeUtf8Replace(data) {
  let out = '';
  scanUtf8(
    data,
    (cp) => {
      if (cp > 0xffff) {
        const x = cp - 0x10000;
        out += String.fromCharCode(0xd800 + (x >> 10), 0xdc00 + (x & 0x3ff));
      } else {
        out += String.fromCharCode(cp);
      }
    },
    () => {
      out += '�';
    }
  );
  return out;
}

// Python repr() for `bytes` and `str`, byte-exact with CPython.

import { isPrintableCp } from './pystr.mjs';

function hex2(n) {
  const s = n.toString(16);
  return s.length < 2 ? '0' + s : s;
}

function hexN(n, width) {
  let s = n.toString(16);
  while (s.length < width) s = '0' + s;
  return s;
}

/**
 * CPython's "smart quote" rule: prefer `'`; switch to `"` only if a `'` is seen
 * and no `"` appears anywhere (the scan aborts back to `'` on the first `"`).
 */
function chooseQuote(codes) {
  let quote = 39; // '
  for (let i = 0; i < codes.length; i++) {
    if (codes[i] === 34) {
      quote = 39;
      break;
    } else if (codes[i] === 39) {
      quote = 34;
    }
  }
  return quote;
}

/** repr() of a Python bytes object, e.g. b'ab\x00'. */
export function bytesRepr(data) {
  const quote = chooseQuote(data);
  const q = String.fromCharCode(quote);
  let out = 'b' + q;
  for (let i = 0; i < data.length; i++) {
    const c = data[i];
    if (c === quote || c === 0x5c) out += '\\' + String.fromCharCode(c);
    else if (c === 0x09) out += '\\t';
    else if (c === 0x0a) out += '\\n';
    else if (c === 0x0d) out += '\\r';
    else if (c < 0x20 || c >= 0x7f) out += '\\x' + hex2(c);
    else out += String.fromCharCode(c);
  }
  return out + q;
}

/** repr() of a Python str object. */
export function strRepr(v) {
  const cps = v.cps;
  const quote = chooseQuote(cps);
  const q = String.fromCharCode(quote);
  let out = q;
  for (let i = 0; i < cps.length; i++) {
    const c = cps[i];
    if (c === quote || c === 0x5c) {
      out += '\\' + String.fromCharCode(c);
    } else if (c === 0x09) {
      out += '\\t';
    } else if (c === 0x0a) {
      out += '\\n';
    } else if (c === 0x0d) {
      out += '\\r';
    } else if (c < 0x20 || c === 0x7f) {
      out += '\\x' + hex2(c);
    } else if (c < 0x7f) {
      out += String.fromCharCode(c);
    } else if (isPrintableCp(c)) {
      if (c > 0xffff) {
        const x = c - 0x10000;
        out += String.fromCharCode(0xd800 + (x >> 10), 0xdc00 + (x & 0x3ff));
      } else {
        out += String.fromCharCode(c);
      }
    } else if (c <= 0xff) {
      out += '\\x' + hexN(c, 2);
    } else if (c <= 0xffff) {
      out += '\\u' + hexN(c, 4);
    } else {
      out += '\\U' + hexN(c, 8);
    }
  }
  return out + q;
}

/** repr() of a single character given its code point (used by ValueError). */
export function charRepr(cp) {
  return strRepr({ cps: [cp] });
}

// Python's int(str) for argparse `type=int`: Unicode whitespace, Unicode Nd
// digits, `_` separators between digits, arbitrary precision.

import { isPySpace } from './pystr.mjs';

// Start code point of every 10-code-point Unicode decimal-digit run
// (General_Category=Nd), Unicode 15.0 — the version shipped with Python 3.12.
const ND_GROUP_STARTS = [
  48, 1632, 1776, 1984, 2406, 2534, 2662, 2790, 2918, 3046, 3174, 3302, 3430,
  3558, 3664, 3792, 3872, 4160, 4240, 6112, 6160, 6470, 6608, 6784, 6800, 6992,
  7088, 7232, 7248, 42528, 43216, 43264, 43472, 43504, 43600, 44016, 65296,
  66720, 68912, 69734, 69872, 69942, 70096, 70384, 70736, 70864, 71248, 71360,
  71472, 71904, 72016, 72784, 73040, 73120, 73552, 92768, 92864, 93008, 120782,
  120792, 120802, 120812, 120822, 123200, 123632, 124144, 125264, 130032,
];

/** Py_UNICODE_TODECIMAL: digit value 0..9, or -1 when not a decimal digit. */
export function decimalValue(cp) {
  let lo = 0;
  let hi = ND_GROUP_STARTS.length - 1;
  while (lo <= hi) {
    const mid = (lo + hi) >> 1;
    const start = ND_GROUP_STARTS[mid];
    if (cp < start) hi = mid - 1;
    else if (cp >= start + 10) lo = mid + 1;
    else return cp - start;
  }
  return -1;
}

// Py_ISSPACE (C locale) — what PyLong_FromString skips.
function isAsciiSpace(code) {
  return (
    code === 0x20 || code === 0x09 || code === 0x0a || code === 0x0b ||
    code === 0x0c || code === 0x0d
  );
}

/**
 * _PyUnicode_TransformDecimalAndSpaceToASCII: code points below 127 pass
 * through, Unicode spaces fold to ' ', decimal digits fold to '0'..'9', and the
 * first other character becomes '?' and truncates the rest.
 */
function transformDecimalAndSpace(cps) {
  let out = '';
  for (let i = 0; i < cps.length; i++) {
    const cp = cps[i];
    if (cp < 127) {
      out += String.fromCharCode(cp);
    } else if (isPySpace(cp)) {
      out += ' ';
    } else {
      const d = decimalValue(cp);
      if (d < 0) {
        out += '?';
        break;
      }
      out += String.fromCharCode(48 + d);
    }
  }
  return out;
}

/**
 * PyLong_FromString(s, 10) on an all-ASCII string.
 * Returns a BigInt, or null when the text is not a valid integer literal.
 */
function longFromAsciiString(s) {
  let i = 0;
  const n = s.length;
  while (i < n && isAsciiSpace(s.charCodeAt(i))) i++;
  let negative = false;
  if (i < n && (s[i] === '+' || s[i] === '-')) {
    negative = s[i] === '-';
    i++;
  }
  let digits = '';
  let prevWasDigit = false;
  let sawDigit = false;
  while (i < n) {
    const ch = s[i];
    if (ch === '_') {
      if (!prevWasDigit) return null;
      prevWasDigit = false;
      i++;
      continue;
    }
    const code = s.charCodeAt(i);
    if (code >= 48 && code <= 57) {
      digits += ch;
      prevWasDigit = true;
