  return decimal;
}

/**
 * b58decode(v).  The ordering matters: str.rstrip() runs on the *str* (line
 * 117), then scrub_input() ascii-encodes (line 118), then the '1' prefix is
 * stripped and b58decode_int() runs (line 124).
 */
export function b58decode(v) {
  const stripped = v instanceof PyStr ? rstripStr(v) : brstripWs(v);
  let data;
  try {
    data = scrubInput(stripped);
  } catch (err) {
    addFrame(err, MODULE, 30, 'scrub_input');
    addFrame(err, MODULE, 118, 'b58decode');
    throw err;
  }
  const origlen = data.length;
  const body = blstripByte(data, ALPHABET_BYTES[0]);
  const newlen = body.length;

  let acc;
  try {
    acc = b58decodeInt(body);
  } catch (err) {
    addFrame(err, MODULE, 124, 'b58decode');
    throw err;
  }

  const result = [];
  while (acc > 0n) {
    const [q, mod] = divmodFloor(acc, 256n);
    acc = q;
    result.push(Number(mod));
  }
  return bconcat(brepeat(0, origlen - newlen), breversed(result));
}

/** b58encode_check(v) */
export function b58encodeCheck(v) {
  const data = scrubInput(v);
  const digest = sha256(sha256(data));
  return b58encode(bconcat(data, bslice(digest, 0, 4)));
}

/** b58decode_check(v) */
export function b58decodeCheck(v) {
  const decoded = b58decode(v);
  const payload = bslice(decoded, 0, decoded.length - 4);
  const check = bslice(decoded, decoded.length - 4, decoded.length);
  const digest = sha256(sha256(payload));
  if (!bequal(check, bslice(digest, 0, 4))) {
    throw new PyValueError('Invalid checksum');
  }
  return payload;
}

// The slice of Python's argparse that this program exercises: six required
// single-value options, -h/--help, prefix abbreviation, `--x=v`, `--`,
// negative-number values, and the exact error strings / exit codes.

import { PyStr, jsFromStr, strFromJs } from './pystr.mjs';
import { strRepr } from './pyrepr.mjs';
import { pyInt } from './pyint.mjs';

const NEGATIVE_NUMBER_RE = /^-\d+$|^-\d*\.\d+$/;

/** Thrown for `parser.error()`; the caller prints usage + message and exits 2. */
export class ArgparseError extends Error {
  constructor(message) {
    super(message);
    this.argparseMessage = message;
  }
}

/** Thrown by the -h/--help action. */
export class ArgparseHelp extends Error {}

export class Parser {
  constructor(prog) {
    this.prog = prog;
