    for (const a of this.actions) {
      for (const s of a.strings) this.optionStrings.set(s, a);
    }
  }

  addOption(name, type) {
    const flag = '--' + name;
    const action = {
      dest: name,
      strings: [flag],
      nargs: 1,
      required: true,
      type,
      metavar: name.toUpperCase(),
    };
    this.actions.push(action);
    this.optionStrings.set(flag, action);
    return action;
  }

  formatUsage() {
    let usage = 'usage: ' + this.prog + ' [-h]';
    for (const a of this.actions) {
      if (a.nargs === 0) continue;
      usage += ' ' + a.strings[0] + ' ' + a.metavar;
    }
    return usage + '\n';
  }

  formatHelp() {
    let out = this.formatUsage();
    out += '\noptions:\n';
    out += '  -h, --help  show this help message and exit\n';
    for (const a of this.actions) {
      if (a.nargs === 0) continue;
      out += '  ' + a.strings[0] + ' ' + a.metavar + '\n';
    }
