   * not option-like, otherwise {action, optionString, explicitArg}; `action`
   * may be null for an unknown option.
   */
  parseOptional(arg) {
    if (arg.length === 0) return null;
    if (arg[0] !== '-') return null;
    if (this.optionStrings.has(arg)) {
      return { action: this.optionStrings.get(arg), optionString: arg, explicitArg: null };
    }
    if (arg.length === 1) return null;
    const eq = arg.indexOf('=');
    if (eq !== -1) {
      const head = arg.slice(0, eq);
      if (this.optionStrings.has(head)) {
        return {
          action: this.optionStrings.get(head),
          optionString: head,
          explicitArg: arg.slice(eq + 1),
        };
      }
    }
    const tuples = this.getOptionTuples(arg);
    if (tuples.length > 1) {
      const names = tuples.map((t) => t.optionString).join(', ');
      throw new ArgparseError(
        'ambiguous option: ' + arg + ' could match ' + names
      );
    }
    if (tuples.length === 1) return tuples[0];
    if (NEGATIVE_NUMBER_RE.test(arg)) return null;
    if (arg.indexOf(' ') !== -1) return null;
    return { action: null, optionString: arg, explicitArg: null };
  }

  getOptionTuples(arg) {
    const result = [];
    if (arg[0] === '-' && arg[1] === '-') {
      const eq = arg.indexOf('=');
      const prefix = eq === -1 ? arg : arg.slice(0, eq);
      const explicitArg = eq === -1 ? null : arg.slice(eq + 1);
      for (const [s, action] of this.optionStrings) {
        if (s.startsWith(prefix)) result.push({ action, optionString: s, explicitArg });
      }
    } else if (arg[0] === '-' && arg[1] !== '-') {
      const shortPrefix = arg.slice(0, 2);
      const shortExplicit = arg.slice(2);
      const explicitArg = arg.slice(1);
      for (const [s, action] of this.optionStrings) {
        if (s === shortPrefix) {
          result.push({ action, optionString: s, explicitArg: shortExplicit });
        } else if (s.startsWith(arg)) {
          result.push({ action, optionString: s, explicitArg });
        }
      }
    }
    return result;
  }

  /**
   * @param {PyStr[]} argv
   * @returns {Object} namespace mapping dest -> value
   */
  parseArgs(argv) {
    const tokens = argv.map((v) => ({ py: v, js: jsFromStr(v) }));
    const namespace = {};
    const seen = new Set();
    const extras = [];

    let i = 0;
    let afterDoubleDash = false;
    while (i < tokens.length) {
      const tok = tokens[i];
      if (afterDoubleDash) {
        extras.push(tok.js);
        i++;
        continue;
      }
      if (tok.js === '--') {
        afterDoubleDash = true;
        extras.push(tok.js);
        i++;
        continue;
      }
      const opt = this.parseOptional(tok.js);
      if (opt === null) {
        extras.push(tok.js);
        i++;
        continue;
      }
      if (opt.action === null) {
        extras.push(tok.js);
        i++;
        continue;
      }
      const action = opt.action;
      if (action.nargs === 0) {
        if (action.dest === 'help') throw new ArgparseHelp();
        i++;
        continue;
      }
      let valuePy = null;
      if (opt.explicitArg !== null) {
        valuePy = strFromJs(opt.explicitArg);
        i++;
      } else {
        const next = tokens[i + 1];
        const nextIsOption =
          next !== undefined && this.parseOptional(next.js) !== null;
        if (next === undefined || nextIsOption) {
          throw new ArgparseError(
            'argument ' + opt.optionString + ': expected one argument'
          );
        }
        valuePy = next.py;
        i += 2;
