      namespace[action.dest] = this.convert(action, opt.optionString, valuePy);
      seen.add(action.dest);
    }

    const missing = [];
    for (const a of this.actions) {
      if (a.required && !seen.has(a.dest)) missing.push(a.strings[0]);
    }
    if (missing.length) {
      throw new ArgparseError(
        'the following arguments are required: ' + missing.join(', ')
      );
    }

    if (extras.length) {
      throw new ArgparseError('unrecognized arguments: ' + extras.join(' '));
    }

    return namespace;
  }

  convert(action, optionString, valuePy) {
    if (action.type === 'int') {
      const n = pyInt(valuePy);
      if (n === null) {
        throw new ArgparseError(
          'argument ' + optionString + ': invalid int value: ' + strRepr(valuePy)
        );
      }
      return n;
    }
    return valuePy;
  }
}

/** Build the parser declared by test19.py. */
export function buildParser(prog) {
  const p = new Parser(prog);
  p.addOption('a', 'str');
  p.addOption('b', 'str');
  p.addOption('c', 'str');
  p.addOption('d', 'str');
  p.addOption('e', 'int');
  p.addOption('f', 'int');
