}

// Recover the true argv bytes.  Node has already decoded process.argv with
// U+FFFD replacement, which loses the distinction Python keeps via
// surrogateescape, so read /proc/self/cmdline and decode it ourselves.

import * as fs from 'node:fs';
import { bytesFromLatin1 } from './pybytes.mjs';
import { decodeUtf8Replace, decodeUtf8Surrogateescape } from './pycodec.mjs';
import { strFromJs } from './pystr.mjs';

function fallback() {
  return process.argv.slice(2).map(strFromJs);
}

/**
 * @returns {import('./pystr.mjs').PyStr[]} the user arguments as Python strs
 */
export function getPyArgv() {
  const want = process.argv.length - 2;
  if (want <= 0) return [];
  let raw;
  try {
    raw = fs.readFileSync('/proc/self/cmdline', 'latin1');
  } catch {
    return fallback();
  }
  const records = raw.split('\0');
  // execve always appends a trailing NUL, producing one empty tail record.
  if (records.length > 0 && records[records.length - 1] === '') records.pop();
  if (records.length < want) return fallback();

  const tail = records.slice(records.length - want);
  const decoded = [];
  for (let i = 0; i < want; i++) {
    const bytes = bytesFromLatin1(tail[i]);
    if (decodeUtf8Replace(bytes) !== process.argv[i + 2]) return fallback();
    decoded.push(decodeUtf8Surrogateescape(bytes));
  }
  return decoded;
}

/** os.path.basename() for the program name argparse prints. */
export function basename(p) {
  const idx = p.lastIndexOf('/');
  return idx === -1 ? p : p.slice(idx + 1);
}

