    bytesRepr(decodedCheckC) + '\n' +
    bytesRepr(encodedD) + '\n' +
    bytesRepr(decodedD) + '\n' +
    bytesRepr(encodedIntE) + '\n' +
    bytesRepr(encodedIntF) + '\n' +
    decodedIntE.toString() + '\n' +
    bytesRepr(encodedCheckDecoded) + '\n'
