export const ALPHABET =
  '123456789ABCDEFGHJKLMNPQRSTUVWXYZabcdefghijkmnopqrstuvwxyz';

const ALPHABET_BYTES = [];
for (let i = 0; i < ALPHABET.length; i++) ALPHABET_BYTES.push(ALPHABET.charCodeAt(i));

const INDEX = new Map();
for (let i = 0; i < ALPHABET_BYTES.length; i++) INDEX.set(ALPHABET_BYTES[i], i);

const MODULE = 'base58/__init__.py';

// 58**9 == 7427658739644928 < 2**53, so a full nine-digit group is exactly
// representable as a double.  Working nine digits at a time keeps the bignum
// arithmetic linear-ish for very long arguments.
const GROUP = 9;
const GROUP_MOD_NUM = 7427658739644928;
const GROUP_MOD = 7427658739644928n;
const POW58 = [1n];
for (let i = 1; i <= GROUP; i++) POW58.push(POW58[i - 1] * 58n);

/** Floor divmod, matching Python's divmod() for negative numerators. */
function divmodFloor(i, base) {
  let q = i / base;
  let r = i % base;
  if (r < 0n) {
    r += base;
    q -= 1n;
  }
  return [q, r];
}

/** scrub_input(): str -> ascii bytes (line 30), bytes -> itself. */
export function scrubInput(v) {
  if (v instanceof PyStr) return encodeAscii(v);
  return v;
}

/** Append the base58 digits of a positive double `v`, padded to `width`. */
function pushGroup(out, v, width) {
  const digits = new Array(width);
  let x = v;
  for (let k = width - 1; k >= 0; k--) {
    const r = x % 58;
    digits[k] = r;
    x = (x - r) / 58;
  }
  for (let k = 0; k < width; k++) out.push(ALPHABET_BYTES[digits[k]]);
}

/**
 * b58encode_int(i, default_one=True)
 *
 * NOTE: a negative `i` never terminates in CPython — floor division pins the
 * accumulator at -1 forever — and the reference binary hangs accordingly.  The
 * negative branch below reproduces that hang.
 */
export function b58encodeInt(i, defaultOne = true) {
  if (i === 0n && defaultOne) return [ALPHABET_BYTES[0]];
  if (i < 0n) {
    let acc = i;
    for (;;) {
      const [q] = divmodFloor(acc, 58n);
      acc = q;
      if (acc === 0n) break; // never reached: acc stays at -1
    }
    return [];
  }
  if (i === 0n) return [];

  // Peel off nine-digit groups from the bottom, most significant group last.
  const groups = [];
  let acc = i;
  while (acc >= GROUP_MOD) {
    const q = acc / GROUP_MOD;
    groups.push(Number(acc - q * GROUP_MOD));
    acc = q;
  }
  const out = [];
  let top = Number(acc);
  const topDigits = [];
  while (top > 0) {
    const r = top % 58;
    topDigits.push(r);
    top = (top - r) / 58;
  }
  for (let k = topDigits.length - 1; k >= 0; k--) out.push(ALPHABET_BYTES[topDigits[k]]);
  for (let g = groups.length - 1; g >= 0; g--) pushGroup(out, groups[g], GROUP);
  return out;
}

/** b58encode(v) */
export function b58encode(v) {
  const data = scrubInput(v);
  const origlen = data.length;
  const stripped = blstripByte(data, 0);
  const newlen = stripped.length;
  const acc = bytesToBigIntBE(stripped);
  const result = b58encodeInt(acc, false);
  return bconcat(brepeat(ALPHABET_BYTES[0], origlen - newlen), result);
}

/** b58decode_int(v); the ValueError is raised on line 104. */
export function b58decodeInt(v) {
  let data = v instanceof PyStr ? rstripStr(v) : brstripWs(v);
  data = scrubInput(data);
  let decimal = 0n;
  let i = 0;
  const n = data.length;
  while (i < n) {
    const take = n - i < GROUP ? n - i : GROUP;
    let block = 0;
    for (let k = 0; k < take; k++) {
      const idx = INDEX.get(data[i + k]);
      if (idx === undefined) {
        const err = new PyValueError('Invalid character ' + charRepr(data[i + k]));
        addFrame(err, MODULE, 104, 'b58decode_int');
        throw err;
      }
      block = block * 58 + idx;
    }
    decimal = decimal * POW58[take] + BigInt(block);
    i += take;
  }
  return decimal;
}

